def nxt(l,n): return chr(ord(l[0])-1)+chr(ord(l[1])-1)+' '+str(n-5)
r=nxt('VI',78)
opts={'A':'VI 74','B':'UH 72','C':'VG 74','D':'UH 73'}
assert r==opts['D']
for k in 'ABC': assert r!=opts[k]

import itertools
# universe of 4 types over (circle,rect,square,tri) membership
types=[t for t in itertools.product([0,1],repeat=4) if not (t[2] and not t[3])]  # all squares are triangles
C,R,S,T=range(4)
def some(pop,a,b): return any(x[a] and x[b] for x in pop)
def allf(pop,a,b): return all(x[b] for x in pop if x[a])
res=None
follows=[True,True,True]
found=False
for n in range(1,5):
    for pop in itertools.combinations(types,n):
        if some(pop,C,R) and some(pop,R,S):
            found=True
            c=[not some(pop,C,T), some(pop,R,T), allf(pop,R,T)]
            follows=[f and x for f,x in zip(follows,c)]
assert found
ans={'A':[1,1,0],'B':[1,0,0],'C':[0,0,1],'D':[0,1,0]}
r=[int(x) for x in follows]
assert r==ans['D']
for k in 'ABC': assert r!=ans[k]

